/* ALPHA Mic Booster — v9 panel (content script, isolated world) */
(async function () {
  if (window.top !== window.self || window.__alphaPanelBuilt) return;
  window.__alphaPanelBuilt = true;

  const LOGO_URL = chrome.runtime.getURL("icons/logo.png");
  const WORDMARK_URL = chrome.runtime.getURL("icons/wordmark.png");
  const FONT_URL = "data:font/truetype;charset=utf-8;base64,"; // embedded as base64 so the font always loads, even if the extension resource fails to fetch
  const OWNER_TELEGRAM = "@ALPHZ";

  // Chrome does not reliably load @font-face rules declared inside a Shadow Root.
  // Registering it on the actual page document (once) makes it available to every
  // shadow root on the page, since font resources are document-scoped.
  function ensureGlobalFont() {
    if (window.__alphaFontInjected) return;
    window.__alphaFontInjected = true;
    try {
      const s = document.createElement("style");
      s.textContent = `@font-face{ font-family:'Boldonse'; src:url('${FONT_URL}') format('truetype'); font-weight:400; font-style:normal; font-display:swap; }`;
      (document.head || document.documentElement).appendChild(s);
    } catch (err) {
      console.error("[ALPHA] font injection failed", err);
    }
  }
  ensureGlobalFont();

  // -----------------------------------------------------------------
  // License-locked placeholder (shown until the seller approves this copy)
  // -----------------------------------------------------------------
  function showLockScreen(status) {
    if (document.getElementById("alpha-lock-host")) return;
    const host = document.createElement("div");
    host.id = "alpha-lock-host";
    host.style.cssText = "all:initial;position:fixed;top:70px;right:12px;z-index:2147483647;font-family:'Boldonse','Arial Black',Impact,sans-serif;";
    const shadow = host.attachShadow({ mode: "open" });

    const card = document.createElement("div");
    card.style.cssText = `width:230px;border-radius:14px;background:#0d0d12 url('${LOGO_URL}') center/cover no-repeat;
      border:1px solid #2a2a35;color:#eee;padding:14px;box-shadow:0 12px 32px rgba(0,0,0,.7);position:relative;overflow:hidden;`;
    const overlay = document.createElement("div");
    overlay.style.cssText = "position:absolute;inset:0;background:linear-gradient(180deg,rgba(10,10,14,.88),rgba(10,10,14,.94));";
    card.appendChild(overlay);

    const inner = document.createElement("div");
    inner.style.cssText = "position:relative;";
    const title = document.createElement("div");
    title.textContent = "ALPHA";
    title.style.cssText = "font-family:'Boldonse','Arial Black',Impact,sans-serif;font-size:16px;font-weight:400;color:#ffffff;letter-spacing:1.5px;margin-bottom:2px;";
    const sub = document.createElement("div");
    sub.textContent = "v9 \u00B7 Mic Booster";
    sub.style.cssText = "font-family:'Boldonse',Segoe UI,system-ui,sans-serif;font-size:9px;color:#8a8a95;letter-spacing:1px;text-transform:uppercase;margin-bottom:10px;";

    const msg = document.createElement("div");
    const setMsg = (s) => { msg.textContent = (s === "revoked" ? "License revoked" : "Waiting for approval") + ". Send the ID below to the owner on Telegram to activate this copy."; };
    msg.style.cssText = "font-family:'Boldonse',Segoe UI,system-ui,sans-serif;font-size:11px;color:#c9c9d2;margin-bottom:10px;line-height:1.4;";
    setMsg(status);

    const idBox = document.createElement("div");
    idBox.style.cssText = "background:#12121a;border:1px solid #2a2a35;border-radius:8px;padding:8px 9px;margin-bottom:10px;";
    const idLabel = document.createElement("div");
    idLabel.textContent = "Owner \u00B7 Telegram " + OWNER_TELEGRAM;
    idLabel.style.cssText = "font-family:'Boldonse',Segoe UI,system-ui,sans-serif;font-size:9.5px;color:#ffffff;font-weight:400;margin-bottom:5px;";
    const idRow = document.createElement("div");
    idRow.style.cssText = "display:flex;align-items:center;gap:6px;";
    const idVal = document.createElement("div");
    idVal.textContent = "Loading ID\u2026";
    idVal.style.cssText = "font-family:'Boldonse',Consolas,monospace;font-size:8px;color:#c9c9d2;word-break:break-all;flex:1;line-height:1.5;";
    const idCopyBtn = document.createElement("button");
    idCopyBtn.textContent = "Copy";
    idCopyBtn.style.cssText = "padding:5px 8px;border-radius:5px;border:1px solid #2a2a35;background:#17171f;color:#eee;font-family:'Boldonse',Segoe UI,system-ui,sans-serif;font-size:9px;font-weight:400;cursor:pointer;flex-shrink:0;";
    idRow.appendChild(idVal); idRow.appendChild(idCopyBtn);
    idBox.appendChild(idLabel); idBox.appendChild(idRow);
    chrome.runtime.sendMessage({ type: "JMB_GET_BUYER_ID" }, (res) => {
      idVal.textContent = (res && res.buyerUuid) || "unavailable";
    });
    idCopyBtn.addEventListener("click", () => {
      navigator.clipboard.writeText(idVal.textContent).then(() => {
        idCopyBtn.textContent = "Copied";
        setTimeout(() => { idCopyBtn.textContent = "Copy"; }, 1200);
      });
    });

    const btn = document.createElement("button");
    btn.textContent = "Check again";
    btn.style.cssText = "width:100%;padding:8px;border-radius:6px;border:1px solid #2a2a35;background:#17171f;color:#eee;font-family:'Boldonse',Segoe UI,system-ui,sans-serif;font-size:11px;font-weight:400;cursor:pointer;";
    btn.addEventListener("click", () => {
      btn.textContent = "Checking\u2026";
      chrome.runtime.sendMessage({ type: "JMB_LICENSE_RECHECK" }, (res) => {
        btn.textContent = "Check again";
        const s = res && res.status;
        if (s === "approved") { host.remove(); window.__alphaPanelBuilt = false; location.reload(); }
        else setMsg(s || "pending");
      });
    });

    inner.appendChild(title); inner.appendChild(sub); inner.appendChild(msg); inner.appendChild(idBox); inner.appendChild(btn);
    card.appendChild(inner);
    shadow.appendChild(card);
    document.documentElement.appendChild(host);
  }

  // TEST MODE (owner only): true skips the approval lock so you can test.
  // Set this to false before giving the extension to any buyer.
  const ALPHA_TEST_MODE = true;
  const { jmbLicenseStatus } = await chrome.storage.local.get("jmbLicenseStatus");
  if (!ALPHA_TEST_MODE && jmbLicenseStatus !== "approved") { showLockScreen(jmbLicenseStatus); return; }

  try {
    const s = document.createElement("script");
    s.src = chrome.runtime.getURL("inject.js");
    s.onload = () => s.remove();
    (document.head || document.documentElement).appendChild(s);
  } catch (err) {
    console.error("[ALPHA] engine injection failed", err);
  }

  // -----------------------------------------------------------------
  // Panel styles
  // -----------------------------------------------------------------
  const STYLE = `
    :host{ all:initial; position:fixed; top:70px; right:12px; z-index:2147483647;
      font-family:'Boldonse','Segoe UI',system-ui,-apple-system,sans-serif; }
    *{ box-sizing:border-box; }
    .bubble{ display:none; width:50px;height:50px;border-radius:50%;
      background:#050505; align-items:center; justify-content:center;
      cursor:pointer; border:2px solid #fff; box-shadow:0 4px 16px rgba(255,255,255,.22); overflow:hidden; }
    .bubble img{ width:72%; height:72%; object-fit:contain; filter:drop-shadow(0 0 5px #ffffffa0); }
    .card{ width:280px; border-radius:14px; position:relative; overflow:hidden;
      background:#0d0d12; border:1px solid #2a2a35; color:#eee;
      box-shadow:0 14px 36px rgba(0,0,0,.65); }
    .bg-logo{ position:absolute; inset:0; background:url('${LOGO_URL}') center 18% / 155% no-repeat;
      opacity:.08; pointer-events:none; filter:grayscale(1) blur(5px); transform:scale(1.04); }
    .bg-fade{ position:absolute; inset:0; background:linear-gradient(180deg, rgba(13,13,18,.55) 0%, #0d0d12 62%); pointer-events:none; }
    .panel-root.closed .card{ display:none; }
    .panel-root.closed .bubble{ display:flex; }
    .header{ display:flex; align-items:center; gap:7px; padding:13px 11px; border-bottom:1px solid #2a2a35;
      cursor:grab; touch-action:none; position:relative; z-index:1; }
    .header .mic{ width:28px; height:28px; flex-shrink:0; object-fit:contain;
      filter:drop-shadow(0 0 3px #ffffffc0) drop-shadow(0 0 9px #ffffff70); }
    .header .titles{ flex:1; min-width:0; }
    .header h1{ margin:0; font-size:0; letter-spacing:.3px; font-weight:400;
      font-family:'Boldonse','Arial Black',Impact,'Haettenschweiler','Segoe UI Black',sans-serif;
      color:#ffffff;
      white-space:nowrap; overflow:hidden; text-overflow:ellipsis; text-transform:uppercase; }
    .header .wordmark{ width:72px; height:23px; object-fit:contain; filter:drop-shadow(0 0 4px #ffffff70); flex-shrink:0; }
    .header .sub{ font-size:8px; color:#8a8a95; letter-spacing:.8px; text-transform:uppercase; margin-top:2px; }
    button, input, select, textarea{ font-family:inherit; }
    .icon-btn{ background:#17171f; border:1px solid #2a2a35; color:#eee; width:20px;height:20px;
      border-radius:6px; cursor:pointer; font-size:10.5px; display:flex; align-items:center; justify-content:center; }
    .icon-btn:hover{ border-color:#ffffff; color:#ffffff; }
    .enable-switch, .switch{ position:relative; width:38px; height:21px; flex-shrink:0; }
    .enable-switch input, .switch input{ opacity:0; width:0; height:0; }
    .es-track, .st{ position:absolute; inset:0; display:block; background:#101010; border:2px solid #ffffff; border-radius:20px; cursor:pointer; transition:background .15s,border-color .15s; box-shadow:none !important; }
    .es-track:before, .st:before{ content:""; position:absolute; height:13px; width:13px; left:2px; top:2px;
      background:#fff; border-radius:50%; transition:left .15s; box-shadow:none !important; transform:none; }
    input:checked + .es-track, input:checked + .st{ background:#101010; border-color:#ffffff; box-shadow:none !important; }
    input:checked + .es-track:before, input:checked + .st:before{ left:21px; transform:none; background:#fff; box-shadow:none !important; }
    .slot-switch .st:before{ width:13px; height:13px; left:2px; top:2px; }
    .slot-switch input:checked + .st:before{ left:17px; transform:none; }
    .card{background:#050505; border-color:#555;}
    .bg-logo{opacity:.08;filter:grayscale(1) blur(5px);transform:scale(1.06);}
    .spider-web{position:absolute;inset:0;pointer-events:none;opacity:.12;background-image:radial-gradient(circle at 50% 35%,transparent 0 9%,#fff 9.3% 9.6%,transparent 10% 20%,#fff 20.3% 20.6%,transparent 21% 32%,#fff 32.3% 32.6%,transparent 33% 46%,#fff 46.3% 46.6%,transparent 47%),repeating-conic-gradient(from 0deg at 50% 35%,transparent 0 8deg,#fff 8.2deg 8.7deg,transparent 9deg 22.5deg);mix-blend-mode:screen;}
    .tabs{ display:flex; border-bottom:1px solid #2a2a35; padding:0 3px; position:relative; z-index:1; overflow-x:auto; }
    .tab{ flex:1; text-align:center; padding:8px 1px; font-size:8.7px; color:#8a8a95; cursor:pointer;
      border-bottom:2px solid transparent; font-weight:400; white-space:nowrap; letter-spacing:.3px; }
    .tab.active{ color:#ffffff; border-bottom-color:#ffffff; }
    .body{ padding:11px 12px; position:relative; z-index:1; }
    .panel{ display:none; }
    .panel.active{ display:block; }
    .status{ display:flex; align-items:center; gap:6px; font-size:9.5px; color:#8a8a95; margin-bottom:8px; }
    .dot{ width:7px; height:7px; border-radius:50%; background:#555; flex-shrink:0; }
    .dot.active{ background:#ffffff; }
    .dot.error{ background:#ffffff; }
    .meter{ height:7px; background:#0a0a0e; border:1px solid #2a2a35; border-radius:5px; overflow:hidden; margin-bottom:12px; }
    .meter-fill{ height:100%; width:0%; background:linear-gradient(90deg,#ffffff,#cccccc,#ffffff); transition:width .08s; }
    .section-label{ font-size:9.5px; letter-spacing:1px; color:#ffffff; font-weight:400; margin:10px 0 7px; text-transform:uppercase; }
    .section-label:first-child{ margin-top:0; }
    .hint{ font-size:8.5px; color:#6c6c78; margin:-4px 0 8px; line-height:1.35; }
    .modes{ display:grid; grid-template-columns:repeat(2,1fr); gap:6px; margin-bottom:6px; }
    .modes button{ background:#111; border:1px solid #3a3a3a; color:#eee; padding:7px 4px;
      border-radius:7px; font-size:9.5px; cursor:pointer; font-weight:400; display:flex; align-items:center; justify-content:center; gap:5px; }
    .modes button img{ width:20px; height:20px; object-fit:contain; filter:drop-shadow(0 0 2px #fff); }
    .modes button{ box-shadow:none; }
    .modes button.active{ background:#111; border-color:#ffffff; color:#fff; box-shadow:none; }
    .voice-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:6px; margin-bottom:4px; }
    .voice-grid button{ background:#17171f; border:1px solid #2a2a35; color:#eee; padding:7px 2px;
      border-radius:7px; font-size:9px; cursor:pointer; font-weight:400; }
    .voice-grid button.active{ background:radial-gradient(circle at 35% 30%,#ffffff,#333333 75%); border-color:#ffffff; color:#fff; }
    .row{ margin-bottom:11px; }
    .row label{ display:flex; justify-content:space-between; font-size:10px; color:#8a8a95; margin-bottom:5px; }
    .row label .val{ color:#ffffff; font-weight:400; }
    input[type=range]{ width:100%; accent-color:#ffffff; }
    .toggle-row{ display:flex; justify-content:space-between; align-items:center; gap:10px; margin-bottom:9px; font-size:10px; color:#fff; }
    .eq-grid{ display:flex; justify-content:space-between; gap:6px; margin-bottom:6px; height:130px; }
    .eq-band{ display:flex; flex-direction:column; align-items:center; flex:1; }
    .eq-band input[type=range]{ writing-mode:vertical-lr; direction:rtl; width:5px; height:100px; accent-color:#ffffff; }
    .eq-band .lbl{ font-size:8px; color:#8a8a95; margin-top:4px; }
    .eq-band .v{ font-size:8px; color:#ffffff; }
    .test-btn{ width:100%; padding:8px; margin-top:4px; border-radius:7px; border:1px solid #2a2a35;
      background:#17171f; color:#eee; font-size:10.5px; font-weight:400; cursor:pointer; }
    .test-btn.on{ background:#ffffff; border-color:#ffffff; }
    .reset-btn{ width:100%; padding:6px; border-radius:6px; border:1px solid #2a2a35; background:#17171f;
      color:#8a8a95; font-size:9px; cursor:pointer; margin-top:2px; }
    .file-btn{ width:100%; padding:9px; border-radius:8px; border:1px dashed #3a3a48; background:#12121a;
      color:#c9c9d2; font-size:10px; cursor:pointer; text-align:center; margin-bottom:8px; }
    .file-btn.loaded{ border-style:solid; border-color:#ffffff; color:#ffffff; }
    .btn-row{ display:flex; gap:6px; margin-bottom:8px; }
    .btn-row button{ flex:1; padding:9px 4px; border-radius:8px; border:1px solid #2a2a35; background:#17171f;
      color:#eee; font-size:10px; font-weight:400; cursor:pointer; }
    .btn-row button.play{ background:#333333; border-color:#777777; }
    .btn-row button.stop{ background:#222222; border-color:#555555; }
    .btn-row button.rec{ background:#222222; border-color:#555555; }
    .btn-row button.rec.on{ background:#ffffff; }
    .btn-row button:disabled{ opacity:.55; cursor:not-allowed; }
    .file-btn,.btn-row button,.reset-btn,.test-btn,.modes button,.voice-grid button{ box-shadow:0 0 0 1px rgba(255,255,255,.05); }
    .file-btn:active,.btn-row button:active,.reset-btn:active,.test-btn:active,.modes button:active,.voice-grid button:active{ transform:scale(.98); }
    /* V9: buttons are flat — no glow, no shadow, no radial highlight */
    button, button:hover, button:active, button.active,
    .file-btn, .btn-row button, .reset-btn, .test-btn, .modes button, .voice-grid button, .sound-pad, .icon-btn, .id-copy{
      box-shadow:none !important; text-shadow:none !important; }
    .modes button img{ filter:none !important; }
    .voice-grid button.active{ background:#17171f !important; border-color:#ffffff !important; color:#ffffff !important; box-shadow:none !important; }
    .auto-gain-row{ border:1px solid #555; border-radius:8px; padding:8px 9px; background:#0b0b0b; }
    .auto-gain-row span{ color:#fff; font-weight:700; }
    .sound-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin:8px 0 7px;}
    .sound-slot{display:grid;grid-template-columns:1fr 38px;align-items:center;gap:5px;background:#0c0c0c;border:1px solid #383838;border-radius:8px;padding:5px;}
    .sound-pad{width:100%;min-height:46px;border:1px solid #555;border-radius:7px;background:#171717;color:#fff;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding:6px 8px;cursor:pointer;}
    .sound-pad:hover,.sound-pad.active{border-color:#fff;background:#252525;}
    .sound-pad b{font-size:11px;letter-spacing:.5px;}
    .sound-pad span{font-size:7.5px;color:#aaa;margin-top:2px;}
    .slot-switch{width:34px;height:20px;}
    .slot-switch .st:before{height:14px;width:14px;}
    .audio-folder{font-size:7.5px;color:#888;border:1px dashed #444;border-radius:7px;padding:7px;margin-bottom:9px;text-align:center;}
    .library{display:flex;flex-direction:column;gap:5px;max-height:180px;overflow:auto;margin:7px 0 9px;padding-right:2px;}
    .library-item{display:flex;align-items:center;gap:5px;background:#101010;border:1px solid #333;border-radius:7px;padding:6px;color:#eee;cursor:pointer;}
    .library-item.active{border-color:#fff;background:#1a1a1a;}
    .library-item .name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:9px;}
    .library-item .mini{width:24px;height:22px;padding:0;border-radius:5px;border:1px solid #444;background:#222;color:#fff;}
    .library-empty{font-size:8px;color:#666;text-align:center;padding:8px;border:1px dashed #333;border-radius:7px;}
    .footer{ font-size:8px; color:#55555f; text-align:center; padding:6px 0 2px; letter-spacing:.5px; }
    .about-logo{ display:block; width:64px; height:64px; margin:2px auto 10px; object-fit:contain;
      filter:drop-shadow(0 0 6px #ffffffa0) drop-shadow(0 0 16px #ffffff55); }
    .about-card{ background:#12121a; border:1px solid #2a2a35; border-radius:9px; padding:10px 11px; margin-bottom:10px; }
    .about-card .k{ font-size:9px; color:#8a8a95; text-transform:uppercase; letter-spacing:.6px; margin-bottom:3px; }
    .about-card .v{ font-size:12px; color:#eee; font-weight:400; }
    .about-card a.v{ color:#ffffff; text-decoration:none; }
    .id-row{ display:flex; align-items:center; gap:6px; }
    .id-row .v{ font-family:'Boldonse',Consolas,monospace; font-size:8px; font-weight:400; color:#c9c9d2; word-break:break-all; flex:1; line-height:1.5; }
    .id-copy{ padding:6px 9px; border-radius:6px; border:1px solid #2a2a35; background:#17171f; color:#eee;
      font-size:9px; font-weight:400; cursor:pointer; flex-shrink:0; }
    .id-copy:hover{ border-color:#ffffff; color:#ffffff; }
    .status-pill{ display:inline-flex; align-items:center; gap:5px; font-size:9.5px; color:#ffffff; font-weight:400; }
    .status-pill .dot{ width:7px; height:7px; border-radius:50%; background:#ffffff; }
  `;

  function build() {
    const host = document.createElement("div");
    host.id = "alpha-host";
    (document.body || document.documentElement).appendChild(host);
    const shadow = host.attachShadow({ mode: "open" });
    const styleEl = document.createElement("style");
    styleEl.textContent = STYLE;
    shadow.appendChild(styleEl);

    const root = document.createElement("div");
    root.className = "panel-root closed";
    root.innerHTML = `
      <div class="bubble" id="bubble"><img src="${LOGO_URL}" alt="Alpha"></div>
      <div class="card">
        <div class="bg-logo"></div>
        <div class="bg-fade"></div><div class="spider-web"></div>
        <div class="header" id="dragHandle">
          <img class="wordmark" src="${WORDMARK_URL}" alt="ALPHA">
          <div class="titles">
            <h1>ALPHA</h1>
            <div class="sub" id="statusSub">v9 \u00B7 Mic Boost</div>
          </div>
          <label class="enable-switch">
            <input type="checkbox" id="enableToggle">
            <span class="es-track"></span>
          </label>
          <div class="icon-btn" id="closeBtn">\u2715</div>
        </div>
        <div class="tabs">
          <div class="tab active" data-tab="boost">BOOST</div>
          <div class="tab" data-tab="eq">EQ</div>
          <div class="tab" data-tab="gate">GATE</div>
          <div class="tab" data-tab="fx">FX</div>
          <div class="tab" data-tab="sound">SOUND</div>
          <div class="tab" data-tab="about">ABOUT</div>
        </div>
        <div class="body">
          <div class="status"><div class="dot" id="statusDot"></div><span id="statusText">Loaded \u2014 join a call to activate</span></div>
          <div class="meter"><div class="meter-fill" id="meterFill"></div></div>

          <div class="panel active" data-panel="boost">
            <div class="section-label">Presets</div>
            <div class="modes" id="modeGrid">
              <button data-mode="ALPHA" class="active"><img src="${chrome.runtime.getURL("icons/lion.svg")}" alt="">ALPHA</button>
              <button data-mode="GOD"><img src="${chrome.runtime.getURL("icons/crown.svg")}" alt="">GOD</button>
              <button data-mode="BEAST"><img src="${chrome.runtime.getURL("icons/wolf.svg")}" alt="">BEAST</button>
              <button data-mode="LORD"><img src="${chrome.runtime.getURL("icons/soldier.svg")}" alt="">LORD</button>
            </div>
            <div class="section-label">Gain</div>
            <div class="row">
              <label>Intensity <span class="val" id="gainVal">6/10</span></label>
              <input type="range" id="gain" min="0" max="10" step="1" value="10">
            </div>
            <div class="section-label">Volume Booster</div>
            <div class="hint">Multiplies the boosted mic signal further. Stacks with Intensity above \u2014 keep an eye on the meter, high values distort fast.</div>
            <div class="row">
              <label>Booster <span class="val" id="boosterVal">1x</span></label>
              <input type="range" id="booster" min="1" max="100" step="1" value="100">
            </div>
            <div class="toggle-row auto-gain-row"><span>AUTO GAIN MAX</span>
              <label class="switch"><input type="checkbox" id="autoGainMax" checked><span class="st"></span></label>
            </div>
            <div class="toggle-row"><span>Disable Auto Gain (AGC)</span>
              <label class="switch"><input type="checkbox" id="agc" checked><span class="st"></span></label>
            </div>
            <div class="toggle-row"><span>Disable Noise Suppression</span>
              <label class="switch"><input type="checkbox" id="ns" checked><span class="st"></span></label>
            </div>
            <button class="test-btn" id="testBtn">\u{1F50A} Test My Mic</button>
          </div>

          <div class="panel" data-panel="eq">
            <div class="section-label">5-Band EQ (\u00B124dB)</div>
            <div class="eq-grid">
              <div class="eq-band"><input type="range" id="eq60" min="-24" max="24" step="1" value="-24" orient="vertical"><div class="lbl">60Hz</div><div class="v" id="eq60Val">0</div></div>
              <div class="eq-band"><input type="range" id="eq250" min="-24" max="24" step="1" value="-24" orient="vertical"><div class="lbl">250Hz</div><div class="v" id="eq250Val">0</div></div>
              <div class="eq-band"><input type="range" id="eq1k" min="-24" max="24" step="1" value="24" orient="vertical"><div class="lbl">1kHz</div><div class="v" id="eq1kVal">0</div></div>
              <div class="eq-band"><input type="range" id="eq4k" min="-24" max="24" step="1" value="-24" orient="vertical"><div class="lbl">4kHz</div><div class="v" id="eq4kVal">0</div></div>
              <div class="eq-band"><input type="range" id="eq12k" min="-24" max="24" step="1" value="-24" orient="vertical"><div class="lbl">12kHz</div><div class="v" id="eq12kVal">0</div></div>
            </div>
            <button class="reset-btn" id="eqResetBtn">Reset EQ</button>
          </div>

          <div class="panel" data-panel="gate">
            <div class="section-label">Noise Gate</div>
            <div class="toggle-row"><span>Enable Gate</span>
              <label class="switch"><input type="checkbox" id="gateEnabled"><span class="st"></span></label>
            </div>
            <div class="row">
              <label>Threshold <span class="val" id="gateThresholdVal">-50dB</span></label>
              <input type="range" id="gateThreshold" min="-70" max="-20" step="1" value="-20">
            </div>
          </div>

          <div class="panel" data-panel="fx">
            <div class="section-label">Heavy Sound</div>
            <div class="toggle-row"><span>Enable Heavy Sound</span>
              <label class="switch"><input type="checkbox" id="heavyEnabled" checked><span class="st"></span></label>
            </div>
            <div class="row">
              <label>Drive <span class="val" id="heavyDriveVal">40/100</span></label>
              <input type="range" id="heavyDrive" min="0" max="100" step="5" value="100">
            </div>

            <div class="section-label">Echo</div>
            <div class="toggle-row"><span>Enable Echo</span>
              <label class="switch"><input type="checkbox" id="echoEnabled"><span class="st"></span></label>
            </div>
            <div class="row">
              <label>Repeats <span class="val" id="echoRepeatsVal">0</span></label>
              <input type="range" id="echoRepeats" min="0" max="9" step="1" value="6">
            </div>
            <div class="hint">0 = no echo, 9 = max repeats at max volume.</div>
            <div class="row">
              <label>Delay <span class="val" id="echoDelayVal">260ms</span></label>
              <input type="range" id="echoDelay" min="50" max="600" step="10" value="250">
            </div>

            <div class="section-label">Voice Changer</div>
            <div class="voice-grid" id="voiceGrid">
              <button data-voice="Normal">Normal</button>
              <button data-voice="Male">Male</button>
              <button data-voice="Female">Female</button>
              <button data-voice="Deep">Deep</button>
              <button data-voice="Baby">Baby</button>
              <button data-voice="Chipmunk">Chipmunk</button>
              <button data-voice="Robot">Robot</button>
            </div>
            <div class="row">
              <label>Manual Pitch <span class="val" id="pitchSemitonesVal">-4 st</span></label>
              <input type="range" id="pitchSemitones" min="-24" max="24" step="1" value="0">
            </div>
          </div>

          <div class="panel" data-panel="sound">
            <div class="section-label">SONG PLAYER</div>
            <div class="hint">Upload any song from your device, or use the default song. Independent of the main ALPHA switch.</div>
            <div class="toggle-row"><span>SONG PLAYER ON</span>
              <label class="switch"><input type="checkbox" id="soundboardEnabled"><span class="st"></span></label>
            </div>
            <input type="file" id="songFile" accept="audio/*" style="display:none">
            <div class="btn-row"><button class="file-btn" id="songUploadBtn">&#128193; Upload Song</button><button id="sbDefaultBtn">&#11088; Default</button></div>
            <div class="audio-folder" id="songName">No song loaded</div>
            <div class="btn-row"><button class="play" id="sbPlayBtn" disabled>&#9654; Play</button><button class="stop" id="sbStopBtn" disabled>&#9632; Stop</button></div>
            <div class="btn-row"><button id="sbLoopBtn">&#128257; Loop: Off</button><button id="sbEffectsBtn">&#10024; Song Effects</button></div>
            <div id="sbFxPanel" style="display:none">
              <div class="toggle-row"><span>Echo</span><label class="switch"><input type="checkbox" data-fx="echo"><span class="st"></span></label></div>
              <div class="row"><label>Echo Repeats <span class="val" id="fxEchoRepeatsVal">4</span></label><input type="range" id="fxEchoRepeats" min="1" max="9" step="1" value="4"></div>
              <div class="row"><label>Echo Delay <span class="val" id="fxEchoDelayVal">300ms</span></label><input type="range" id="fxEchoDelay" min="100" max="800" step="10" value="300"></div>
              <div class="toggle-row"><span>Reverb</span><label class="switch"><input type="checkbox" data-fx="reverb"><span class="st"></span></label></div>
              <div class="toggle-row"><span>Chorus</span><label class="switch"><input type="checkbox" data-fx="chorus"><span class="st"></span></label></div>
              <div class="toggle-row"><span>Tremolo</span><label class="switch"><input type="checkbox" data-fx="tremolo"><span class="st"></span></label></div>
              <div class="toggle-row"><span>Distortion</span><label class="switch"><input type="checkbox" data-fx="distortion"><span class="st"></span></label></div>
              <div class="toggle-row"><span>Robot Voice</span><label class="switch"><input type="checkbox" data-fx="robot"><span class="st"></span></label></div>
              <div class="toggle-row"><span>Telephone</span><label class="switch"><input type="checkbox" data-fx="telephone"><span class="st"></span></label></div>
              <div class="toggle-row"><span>Bass Boost</span><label class="switch"><input type="checkbox" data-fx="bass"><span class="st"></span></label></div>
              <div class="row"><label>Speed <span class="val" id="fxSpeedVal">1.00x</span></label><input type="range" id="fxSpeed" min="50" max="150" step="5" value="100"></div>
              <div class="btn-row"><button id="fxResetBtn">Reset Effects</button></div>
              <div class="hint">Effects apply the next time you press Play.</div>
            </div>
            <div class="toggle-row"><span>Apply Voice FX to Sound</span>
              <label class="switch"><input type="checkbox" id="sbFxEnabled"><span class="st"></span></label>
            </div>
            <div class="row"><label>Sound Volume <span class="val" id="sbVolumeVal">100%</span></label><input type="range" id="sbVolume" min="0" max="200" step="5" value="100"></div>

            <div class="section-label">RECORD &amp; SAVE <span id="recTimer" style="float:right;color:#fff">00:00</span></div>
            <div class="hint">Recordings are automatically saved and downloaded to your Downloads folder when recording stops.</div>
            <div class="btn-row"><button class="rec" id="recBtn">● Record</button><button id="recPlayBtn" disabled>▶ Play Last</button></div>
            <div class="btn-row"><button id="recSaveBtn" disabled>↓ Save to Downloads</button><button id="recStopBtn" disabled>■ Stop</button></div>
            <div class="btn-row"><button id="recTestBtn">&#129514; Test Record</button></div>
            <div id="recLibrary" class="library"></div>
          </div>

          <div class="panel" data-panel="about">
            <img class="about-logo" src="${LOGO_URL}" alt="Alpha">
            <div class="about-card">
              <div class="k">License Status</div>
              <span class="status-pill"><span class="dot"></span>Approved</span>
            </div>
            <div class="about-card">
              <div class="k">Owner \u00B7 Telegram</div>
              <a class="v" id="ownerTelegram" href="https://t.me/${OWNER_TELEGRAM.replace('@','')}" target="_blank" rel="noopener">${OWNER_TELEGRAM}</a>
            </div>
            <div class="about-card">
              <div class="k">Your License / Token ID</div>
              <div class="id-row">
                <div class="v" id="aboutTokenId">Loading\u2026</div>
                <button class="id-copy" id="aboutCopyBtn">Copy</button>
              </div>
              <div class="hint" style="margin-top:6px;">Send this ID to the owner on Telegram for support, renewals or transfers.</div>
            </div>
            <div class="about-card">
              <div class="k">Version</div>
              <div class="v" id="aboutVersion">ALPHA v9.0</div>
            </div>
          </div>

          <div class="footer">ALPHA v9 \u00B7 ${OWNER_TELEGRAM}</div>
        </div>
      </div>
    `;
    shadow.appendChild(root);

    const $ = (sel) => shadow.querySelector(sel);
    let state = { soundboardEnabled: true, autoGainMax: false };
    let hydrating = false;
    let testOn = false;

    // Draggable header
    (function makeDraggable() {
      const handle = $("#dragHandle");
      let dragging = false, offX = 0, offY = 0;
      handle.addEventListener("pointerdown", (e) => {
        dragging = true;
        offX = e.clientX - host.offsetLeft;
        offY = e.clientY - host.offsetTop;
        handle.setPointerCapture(e.pointerId);
      });
      handle.addEventListener("pointermove", (e) => {
        if (!dragging) return;
        host.style.left = (e.clientX - offX) + "px";
        host.style.top = (e.clientY - offY) + "px";
        host.style.right = "auto";
      });
      handle.addEventListener("pointerup", () => { dragging = false; });
    })();

    $("#bubble").addEventListener("click", () => root.classList.remove("closed"));
    $("#closeBtn").addEventListener("click", () => root.classList.add("closed"));

    // About tab: version + license/token id
    (function initAbout() {
      const versionEl = $("#aboutVersion");
      if (versionEl) {
        const m = chrome.runtime.getManifest();
        versionEl.textContent = "ALPHA " + (m.version_name || ("v" + m.version));
      }
      const idEl = $("#aboutTokenId");
      const copyBtn = $("#aboutCopyBtn");
      if (idEl) {
        chrome.runtime.sendMessage({ type: "JMB_GET_BUYER_ID" }, (res) => {
          idEl.textContent = (res && res.buyerUuid) || "unavailable";
        });
      }
      if (copyBtn) {
        copyBtn.addEventListener("click", () => {
          const text = idEl ? idEl.textContent : "";
          if (!text || text === "unavailable" || text === "Loading\u2026") return;
          navigator.clipboard.writeText(text).then(() => {
            copyBtn.textContent = "Copied";
            setTimeout(() => { copyBtn.textContent = "Copy"; }, 1200);
          });
        });
      }
    })();

    shadow.querySelectorAll(".tab").forEach((tab) => {
      tab.addEventListener("click", () => {
        shadow.querySelectorAll(".tab").forEach((t) => t.classList.remove("active"));
        shadow.querySelectorAll(".panel").forEach((p) => p.classList.remove("active"));
        tab.classList.add("active");
        shadow.querySelector(`.panel[data-panel="${tab.dataset.tab}"]`).classList.add("active");
      });
    });

    function pushState(patch) {
      state = Object.assign({}, state, patch);
      try { chrome.storage.local.set({ jmbState: state }); } catch (_) {}
      window.postMessage({ type: "ALPHA_SET_STATE", value: patch }, "*");
    }

    function bindRange(id, key, fmt) {
      const input = $("#" + id), out = $("#" + id + "Val");
      input.addEventListener("input", () => {
        const v = parseFloat(input.value);
        if (out) out.textContent = fmt(v);
        if (!hydrating) pushState({ [key]: v });
      });
    }
    function bindToggle(id, key) {
      $("#" + id).addEventListener("change", (e) => { if (!hydrating) pushState({ [key]: e.target.checked }); });
    }

    // Boost
    bindRange("gain", "intensity", (v) => v.toFixed(0) + "/10");
    bindRange("booster", "boosterX", (v) => v.toFixed(0) + "x");
    bindToggle("agc", "disableAGC");
    bindToggle("autoGainMax", "autoGainMax");
    bindToggle("ns", "disableNS");
    shadow.querySelectorAll("#modeGrid button").forEach((btn) => {
      btn.addEventListener("click", () => {
        window.postMessage({ type: "ALPHA_APPLY_MODE", name: btn.dataset.mode }, "*");
        highlightMode(btn.dataset.mode);
      });
    });
    function highlightMode(name) {
      shadow.querySelectorAll("#modeGrid button").forEach((b) => b.classList.toggle("active", b.dataset.mode === name));
    }

    // EQ
    ["eq60", "eq250", "eq1k", "eq4k", "eq12k"].forEach((id) => {
      bindRange(id, id, (v) => (v > 0 ? "+" : "") + v);
    });
    $("#eqResetBtn").addEventListener("click", () => {
      ["eq60", "eq250", "eq1k", "eq4k", "eq12k"].forEach((id) => { $("#" + id).value = 0; $("#" + id + "Val").textContent = "0"; });
      pushState({ eq60: 0, eq250: 0, eq1k: 0, eq4k: 0, eq12k: 0 });
    });

    // Gate
    bindToggle("gateEnabled", "gateEnabled");
    bindRange("gateThreshold", "gateThreshold", (v) => v + "dB");

    // FX — heavy / echo / voice
    bindToggle("heavyEnabled", "heavyEnabled");
    bindRange("heavyDrive", "heavyDrive", (v) => v.toFixed(0) + "/100");
    bindToggle("echoEnabled", "echoEnabled");
    bindRange("echoRepeats", "echoRepeats", (v) => v.toFixed(0));
    bindRange("echoDelay", "echoDelay", (v) => v.toFixed(0) + "ms");
    bindRange("pitchSemitones", "pitchSemitones", (v) => (v > 0 ? "+" : "") + v.toFixed(0) + " st");
    shadow.querySelectorAll("#voiceGrid button").forEach((btn) => {
      btn.addEventListener("click", () => {
        window.postMessage({ type: "ALPHA_APPLY_VOICE", name: btn.dataset.voice }, "*");
        highlightVoice(btn.dataset.voice);
      });
    });
    function highlightVoice(name) {
      shadow.querySelectorAll("#voiceGrid button").forEach((b) => b.classList.toggle("active", b.dataset.voice === name));
    }

    // Enable + test
    $("#enableToggle").addEventListener("change", (e) => {
      pushState({ enabled: e.target.checked });
      $("#statusSub").textContent = e.target.checked ? "v9 \u00B7 Mic Boost" : "v9 \u00B7 Bypassed";
    });
    $("#testBtn").addEventListener("click", () => {
      testOn = !testOn;
      $("#testBtn").classList.toggle("on", testOn);
      $("#testBtn").textContent = testOn ? "\u23F9 Stop Test" : "\u{1F50A} Test My Mic";
      window.postMessage({ type: testOn ? "ALPHA_START_TEST" : "ALPHA_STOP_TEST" }, "*");
    });

    // Song player — upload / default song, loop, effects
    let localAudio = null;
    let lastRecordingId = null;
    let songLoaded = false;
    let songName = "";
    const FX_DEFAULTS = { echo:false, echoRepeats:4, echoDelay:300, reverb:false, chorus:false, tremolo:false,
      distortion:false, robot:false, telephone:false, bass:false, speed:100 };
    function sendStore(type, payload={}) { return new Promise(resolve => chrome.runtime.sendMessage(Object.assign({type}, payload), res => resolve(res || {}))); }
    function blobToB64(blob){ return new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result).split(",")[1] || ""); r.onerror = () => rej(r.error); r.readAsDataURL(blob); }); }
    function b64ToBlob(b64, type){ const bin = atob(b64); const u = new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u[i] = bin.charCodeAt(i); return new Blob([u], {type: type || "audio/webm"}); }
    function fmtTime(sec){ const t=Math.round(sec||0); return Math.floor(t/60)+":"+String(t%60).padStart(2,"0"); }
    function stopLocalAudio(){
      if(localAudio){ try{localAudio.pause(); localAudio.currentTime=0;}catch(_){} localAudio=null; }
      $('#sbStopBtn').disabled=true; $('#recStopBtn').disabled=true;
    }
    function songFx(){ return Object.assign({}, FX_DEFAULTS, state.songFx || {}); }
    function syncSongFxUi(){
      const f = songFx();
      shadow.querySelectorAll('input[data-fx]').forEach(el=>{ el.checked = !!f[el.dataset.fx]; });
      $('#fxEchoRepeats').value = f.echoRepeats; $('#fxEchoRepeatsVal').textContent = f.echoRepeats;
      $('#fxEchoDelay').value = f.echoDelay; $('#fxEchoDelayVal').textContent = f.echoDelay + "ms";
      $('#fxSpeed').value = f.speed; $('#fxSpeedVal').textContent = (f.speed/100).toFixed(2) + "x";
      const on = !!state.songLoop;
      $('#sbLoopBtn').classList.toggle('on', on);
      $('#sbLoopBtn').textContent = on ? "\u{1F501} Loop: On" : "\u{1F501} Loop: Off";
    }
    function setSongFx(patch){ if(hydrating) return; pushState({ songFx: Object.assign({}, songFx(), patch) }); }
    function playSong(){
      if(!$('#soundboardEnabled').checked){ $('#statusText').textContent='Song Player OFF — turn ON its switch'; return; }
      if(!songLoaded){ $('#statusText').textContent='Load a song first'; return; }
      $('#statusText').textContent = 'Playing — ' + songName;
      window.postMessage({type:'ALPHA_SB_PLAY'},'*');
    }
    function sendSongBuffer(buf, name){
      songName = name; songLoaded = false;
      $('#statusText').textContent = 'Loading — ' + name;
      window.postMessage({type:'ALPHA_SB_LOAD', buffer: buf}, '*');
    }

    $('#songUploadBtn').addEventListener('click',()=>$('#songFile').click());
    $('#songFile').addEventListener('change', async (e)=>{
      const file = e.target.files && e.target.files[0];
      e.target.value = '';
      if(!file) return;
      if(!(file.type.startsWith('audio/') || /\.(mp3|wav|ogg|m4a|aac|flac|webm|opus)$/i.test(file.name))){
        $('#statusText').textContent='Please choose an audio file'; return;
      }
      try{ sendSongBuffer(await file.arrayBuffer(), file.name); }
      catch(err){ $('#statusText').textContent='Could not read that file'; }
    });
    $('#sbDefaultBtn').addEventListener('click', async ()=>{
      try{
        const r = await fetch(chrome.runtime.getURL('AUDIO/s1.mp3'), {cache:'no-store'});
        if(!r.ok) throw new Error('HTTP '+r.status);
        sendSongBuffer(await r.arrayBuffer(), 'Default (s1.mp3)');
      }catch(err){ $('#statusText').textContent='Default song missing — AUDIO/s1.mp3'; }
    });
    $('#sbPlayBtn').addEventListener('click', playSong);
    $('#sbStopBtn').addEventListener('click',()=>{stopLocalAudio();window.postMessage({type:'ALPHA_SB_STOP'},'*');});
    $('#sbLoopBtn').addEventListener('click',()=>{ pushState({ songLoop: !state.songLoop }); syncSongFxUi(); });
    $('#soundboardEnabled').addEventListener('change',e=>pushState({soundboardEnabled:e.target.checked}));
    $('#sbEffectsBtn').addEventListener('click',()=>{
      const panel=$('#sbFxPanel'); const open = panel.style.display === 'none';
      panel.style.display = open ? 'block' : 'none';
      $('#sbEffectsBtn').classList.toggle('on', open);
    });
    shadow.querySelectorAll('input[data-fx]').forEach(el=>el.addEventListener('change',()=>setSongFx({[el.dataset.fx]: el.checked})));
    $('#fxEchoRepeats').addEventListener('input',e=>{ const v=Number(e.target.value); $('#fxEchoRepeatsVal').textContent=v; setSongFx({echoRepeats:v}); });
    $('#fxEchoDelay').addEventListener('input',e=>{ const v=Number(e.target.value); $('#fxEchoDelayVal').textContent=v+"ms"; setSongFx({echoDelay:v}); });
    $('#fxSpeed').addEventListener('input',e=>{ const v=Number(e.target.value); $('#fxSpeedVal').textContent=(v/100).toFixed(2)+"x"; setSongFx({speed:v}); });
    $('#fxResetBtn').addEventListener('click',()=>{ pushState({ songFx: Object.assign({}, FX_DEFAULTS) }); syncSongFxUi(); });
    bindToggle('sbFxEnabled','sbFxEnabled');
    bindRange('sbVolume','sbVolume',v=>v.toFixed(0)+'%');
    $('#sbVolume').addEventListener('input',e=>{if(!hydrating){pushState({sbVolume:parseFloat(e.target.value)/100});if(localAudio)localAudio.volume=Math.min(1,parseFloat(e.target.value)/100);}});

    // Mic on => song player off (turning the main switch ON, or moving a mic volume slider)
    function songOffForMic(){
      if(!$('#soundboardEnabled').checked) return;
      $('#soundboardEnabled').checked = false;
      pushState({soundboardEnabled:false});
      stopLocalAudio();
      window.postMessage({type:'ALPHA_SB_STOP'},'*');
      $('#statusText').textContent='Song Player OFF — mic is on';
    }
    $('#enableToggle').addEventListener('change',e=>{ if(e.target.checked) songOffForMic(); });
    $('#gain').addEventListener('change',songOffForMic);
    $('#booster').addEventListener('change',songOffForMic);

    // Recorder — reliable start/stop, timer, persistent library and Downloads copy
    let recording=false, recordingStartedAt=0, recordTimerId=null;
    function setRecTimer(ms){ const sec=Math.max(0,Math.floor(ms/1000)); $('#recTimer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0'); }
    function startRecTimer(){ recordingStartedAt=Date.now(); setRecTimer(0); clearInterval(recordTimerId); recordTimerId=setInterval(()=>setRecTimer(Date.now()-recordingStartedAt),250); }
    function stopRecTimer(){ clearInterval(recordTimerId); recordTimerId=null; }
    async function downloadRecording(id){
      const res=await sendStore('ALPHA_MEDIA_GET',{id}); if(!res.b64) return;
      const url=URL.createObjectURL(b64ToBlob(res.b64,res.type));
      const a=document.createElement('a'); a.href=url; a.download=(res.name||'alpha-recording').replace(/[^a-z0-9 _.-]/gi,'_')+'.webm'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),3000);
    }
    function setRecordingUi(on){
      recording=on; $('#recBtn').classList.toggle('on',on); $('#recBtn').textContent=on?'■ Stop Recording':'● Record';
      $('#recStopBtn').disabled=!on; if(on) startRecTimer(); else stopRecTimer();
    }
    $('#recBtn').addEventListener('click',()=>{
      if(!recording){ setRecordingUi(true); window.postMessage({type:'ALPHA_REC_START'},'*'); }
      else { setRecordingUi(false); window.postMessage({type:'ALPHA_REC_STOP'},'*'); }
    });
    $('#recStopBtn').addEventListener('click',()=>{ if(recording){ setRecordingUi(false); window.postMessage({type:'ALPHA_REC_STOP'},'*'); } });
    $('#recPlayBtn').addEventListener('click',async()=>{
      if(!lastRecordingId)return;
      const res=await sendStore('ALPHA_MEDIA_GET',{id:lastRecordingId});
      if(!res.b64){ $('#statusText').textContent='Could not load that recording'; return; }
      stopLocalAudio();
      const url=URL.createObjectURL(b64ToBlob(res.b64,res.type));
      const a=new Audio(url); a.preload='auto'; a.volume=Math.min(1,Math.max(0,Number(state.sbVolume??1))); localAudio=a;
      a.onended=()=>{ if(localAudio===a) localAudio=null; URL.revokeObjectURL(url); };
      try{ await a.play(); }catch(e){ $('#statusText').textContent='Recording playback blocked — tap Play again'; }
    });
    $('#recSaveBtn').addEventListener('click',()=>{if(lastRecordingId)downloadRecording(lastRecordingId);});
    // Test recorder: 5 seconds, not saved to the library, played back right away to prove it works
    let recTestPending = false;
    $('#recTestBtn').addEventListener('click',()=>{
      if(recTestPending && recording){ setRecordingUi(false); window.postMessage({type:'ALPHA_REC_STOP'},'*'); return; }
      if(recording) return;
      recTestPending = true; setRecordingUi(true);
      $('#recTestBtn').textContent = '■ Stop Test';
      $('#statusText').textContent = 'Test recording — press Stop Test to finish';
      window.postMessage({type:'ALPHA_REC_TEST'},'*');
    });
    async function refreshLibraries(){ const res=await sendStore('ALPHA_MEDIA_LIST'); const recs=(res.items||[]).filter(x=>x.kind==='recording'); const el=$('#recLibrary'); el.innerHTML=''; if(!recs.length){el.innerHTML='<div class="library-empty">No recordings yet</div>';return;} recs.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)); recs.forEach(item=>{const row=document.createElement('div');row.className='library-item';row.innerHTML='<span class="name">'+escapeHtml(item.name)+'</span><button class="mini playMini">▶</button>';row.addEventListener('click',()=>{lastRecordingId=item.id;$('#recPlayBtn').disabled=false;$('#recSaveBtn').disabled=false;row.classList.add('active');});row.querySelector('.playMini').addEventListener('click',async e=>{e.stopPropagation();lastRecordingId=item.id;$('#recPlayBtn').disabled=false;$('#recSaveBtn').disabled=false;await $('#recPlayBtn').click();});el.appendChild(row);}); }
    refreshLibraries();

    // Hydrate UI from saved state
    function hydrate() {
      hydrating = true;
      const gain = state.intensity ?? 6;
      $("#gain").value = gain; $("#gainVal").textContent = gain.toFixed(0) + "/10";
      const booster = state.boosterX ?? 1;
      $("#booster").value = booster; $("#boosterVal").textContent = booster.toFixed(0) + "x";
      $("#agc").checked = state.disableAGC ?? true;
      $("#autoGainMax").checked = state.autoGainMax ?? false;
      $("#ns").checked = state.disableNS ?? false;

      ["eq60", "eq250", "eq1k", "eq4k", "eq12k"].forEach((id) => {
        const v = state[id] ?? 0;
        $("#" + id).value = v; $("#" + id + "Val").textContent = (v > 0 ? "+" : "") + v;
      });

      $("#gateEnabled").checked = state.gateEnabled ?? false;
      const gt = state.gateThreshold ?? -50;
      $("#gateThreshold").value = gt; $("#gateThresholdVal").textContent = gt + "dB";

      $("#heavyEnabled").checked = state.heavyEnabled ?? true;
      const hd = state.heavyDrive ?? 40;
      $("#heavyDrive").value = hd; $("#heavyDriveVal").textContent = hd.toFixed(0) + "/100";

      $("#echoEnabled").checked = state.echoEnabled ?? false;
      const er = state.echoRepeats ?? 0;
      $("#echoRepeats").value = er; $("#echoRepeatsVal").textContent = er.toFixed(0);
      const ed = state.echoDelay ?? 260;
      $("#echoDelay").value = ed; $("#echoDelayVal").textContent = ed.toFixed(0) + "ms";

      const ps = state.pitchSemitones ?? -4;
      $("#pitchSemitones").value = ps; $("#pitchSemitonesVal").textContent = (ps > 0 ? "+" : "") + ps.toFixed(0) + " st";
      if (state.voicePreset) highlightVoice(state.voicePreset);

      $("#sbFxEnabled").checked = state.sbFxEnabled ?? false;
      $("#soundboardEnabled").checked = state.soundboardEnabled ?? true;
      const sbv = Math.round((state.sbVolume ?? 1) * 100);
      $("#sbVolume").value = sbv; $("#sbVolumeVal").textContent = sbv + "%";
      syncSongFxUi();

      $("#enableToggle").checked = state.enabled ?? true;
      $("#statusSub").textContent = (state.enabled ?? true) ? "v9 \u00B7 Mic Boost" : "v9 \u00B7 Bypassed";
      if (state.mode) highlightMode(state.mode);
      hydrating = false;
    }

    try {
      chrome.storage.local.get(["jmbState"], (res) => { state = (res && res.jmbState) || {}; hydrate(); });
    } catch (_) { hydrate(); }

    // Engine -> panel messages
    window.addEventListener("message", (ev) => {
      if (ev.source !== window || !ev.data) return;
      const msg = ev.data;

      if (msg.type === "ALPHA_LEVEL") {
        $("#meterFill").style.width = msg.level + "%";
      } else if (msg.type === "ALPHA_PONG") {
        if (msg.hooked) {
          $("#statusDot").classList.remove("error"); $("#statusDot").classList.add("active");
          $("#statusText").textContent = "Live \u2014 boost active";
        } else {
          $("#statusText").textContent = "Loaded \u2014 join a call to activate";
        }
      } else if (msg.type === "ALPHA_HOOKED") {
        $("#statusDot").classList.remove("error"); $("#statusDot").classList.add("active");
        $("#statusText").textContent = "Live \u2014 boost active";
      } else if (msg.type === "ALPHA_ERROR") {
        if(recording){ setRecordingUi(false); }
        $("#statusDot").classList.add("error");
        $("#statusText").textContent = "Error: " + msg.message;
      } else if (msg.type === "ALPHA_STATE_SYNC") {
        state = msg.value; hydrate();
      } else if (msg.type === "ALPHA_SB_LOADED") {
        songLoaded = true;
        $("#songName").textContent = songName + " \u00B7 " + fmtTime(msg.duration);
        $("#sbPlayBtn").disabled = false;
        playSong();
      } else if (msg.type === "ALPHA_SB_PLAYING") {
        $("#sbStopBtn").disabled = false;
      } else if (msg.type === "ALPHA_SB_ENDED") {
        $("#sbStopBtn").disabled = true;
      } else if (msg.type === "ALPHA_REC_STARTED") {
        setRecordingUi(true);
        $("#statusText").textContent = "Recording…";
      } else if (msg.type === "ALPHA_REC_DONE") {
        setRecordingUi(false);
        if (recTestPending) {
          recTestPending = false;
          $("#recTestBtn").textContent = "\u{1F9EA} Test Record";
          if (!msg.blob || !msg.blob.size) {
            $("#statusText").textContent = "Test failed: nothing recorded — check Test My Mic / song / call";
          } else {
            const ua = URL.createObjectURL(msg.blob);
            const ta = new Audio(ua);
            ta.onended = () => URL.revokeObjectURL(ua);
            ta.play().catch(() => {});
            $("#statusText").textContent = "Test OK: " + (msg.blob.size / 1024).toFixed(0) + " KB recorded — playing back";
          }
        } else if (!msg.blob || !msg.blob.size) {
          $("#statusText").textContent = "Recording was empty — play a song or join a call, then record";
        } else {
          const id = "recording_" + Date.now();
          blobToB64(msg.blob)
            .then((b64) => sendStore("ALPHA_MEDIA_SAVE", {id, kind:"recording", name:"ALPHA v9.2 Recording " + new Date().toLocaleString(), mimeType: msg.blob.type || "audio/webm", b64}))
            .then(async (res) => {
              if (!res || !res.ok) { $("#statusText").textContent = "Recording save failed"; return; }
              lastRecordingId = id; $("#recPlayBtn").disabled = false; $("#recSaveBtn").disabled = false;
              $("#statusText").textContent = "Recording saved";
              await downloadRecording(id); refreshLibraries();
            });
        }
      }
    });

    window.postMessage({ type: "ALPHA_PING" }, "*");
    window.postMessage({ type: "ALPHA_GET_STATE" }, "*");

    try {
      chrome.runtime.onMessage.addListener((msg) => {
        if (msg && msg.type === "JMB_TOGGLE_PANEL") root.classList.toggle("closed");
      });
    } catch (_) {}

    // Alpha Social app: popup signals through storage; only the visible page reacts.
    try {
      chrome.storage.onChanged.addListener((changes, area) => {
        if (area === "local" && changes.jmbTogglePanel && document.visibilityState === "visible") {
          root.classList.toggle("closed");
        }
      });
    } catch (_) {}
  }

  build();
})();
